// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INIT_DISTRIBUTED = 200000000e18;

    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != address(0) && b != address(0));
        vm.assume(a != b);
        vm.assume(a != address(this) && b != address(this));

        // Both actors claim the free airdrop through the public entry getTokens
        vm.prank(a);
        c.getTokens();
        vm.prank(b);
        c.getTokens();

        uint256 balA = c.balanceOf(a);
        uint256 balB = c.balanceOf(b);
        uint256 distGrowth = c.totalDistributed() - INIT_DISTRIBUTED;

        // General rule: tokens credited to recipients exactly accumulate —
        // the sum of their balances equals the total amount recorded as distributed.
        assertTrue(balA + balB == distGrowth);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address k) public {
        // Drive the contract through the XBornID entry (constructor-equivalent setup)
        c.XBornID();

        // General rule: for any address k, balanceOf(k) must equal the distribution credit.
        // The owner was distributed totalDistributed; every other address has zero.
        uint256 expected = (k == c.owner()) ? c.totalDistributed() : 0;
        assertTrue(c.balanceOf(k) == expected);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function checkOwnerFunded() public {
        assert(c.balanceOf(address(this)) == c.totalDistributed());
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address o) public {
        assert(c.balanceOf(o) <= c.totalDistributed());
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address spender, address to, uint256 amt) public {
        require(spender != address(0));
        require(to != address(0));
        require(amt > 0);

        // acquire tokens via the airdrop (this contract is not blacklisted yet)
        c.getTokens{value: 0}();

        require(amt <= c.balanceOf(address(this)));

        c.approve(spender, amt);
        c.transferFrom(address(this), to, amt);

        assert(c.allowance(address(this), spender) == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(msg.sender == address(this));
        c.XBornID();
        assert(c.balanceOf(address(this)) == c.totalDistributed());
    }
    receive() external payable {}
}
